import * as T from './vendor/three.module.js';
export const PULLEY_BAND={id:'band-brown',name:'Brown pulley band · 185 mm',partNumber:'92001',belt:true,noBore:true,group:'extras',color:'#a77546',thickness:3,slots:[],reference:'https://shop.knexusergroup.org.uk/products/92001',geometryStatus:'Supplier approximate 185 mm unstretched length and 3 × 3 mm section; length convention, tension and stretch limits unverified'};
export const BELT_REFERENCE='https://www.knexusergroup.org.uk/en/knex-hint-W7.html';
// Existing reconstructed pulley rim groove: core radius is 1.5 mm below flange.
// A 3 mm belt centerline is consequently at the nominal flange radius.
export const pulleyRadius=d=>['h-small','h-medium'].includes(d.id)?d.diameter/2:null;
export function validateBelt(p,d){if(p.belt===undefined){if(d.belt)throw Error('A pulley band needs its fitted shape.');return;}const b=p.belt;if(!d.belt||!b||!Number.isFinite(b.span)||b.span>1000||!Array.isArray(b.radii)||b.radii.length!==2||b.radii.some(r=>![18.5,25].includes(r))||b.span<=b.radii[0]+b.radii[1]+3)throw Error('Invalid pulley-band shape.');}
export function beltOutline(b={span:130,radii:[18.5,25]}){const [a,c]=b.radii,theta=Math.acos((a-c)/b.span),points=[];for(const [x,r,start,end]of[[0,a,theta,2*Math.PI-theta],[b.span,c,2*Math.PI-theta,2*Math.PI+theta]]){const steps=Math.max(16,Math.ceil((end-start)*16));for(let i=0;i<=steps;i++){const angle=start+(end-start)*i/steps;points.push({pos:[x+r*Math.cos(angle),r*Math.sin(angle),0],normal:[Math.cos(angle),Math.sin(angle),0]});}}return points;}
export function beltLength(b){const [a,c]=b.radii,theta=Math.acos((a-c)/b.span);return 2*Math.sqrt(b.span*b.span-(a-c)**2)+a*(2*Math.PI-2*theta)+c*2*theta;}
export function beltGeometry(d,p={}){const points=beltOutline(p.belt),shape=new T.Shape(),hole=new T.Path(),half=d.thickness/2;for(let i=0;i<points.length;i++){const v=points[i],x=v.pos[0]+v.normal[0]*half,y=v.pos[1]+v.normal[1]*half;i?shape.lineTo(x,y):shape.moveTo(x,y);}shape.closePath();for(let i=points.length-1;i>=0;i--){const v=points[i],x=v.pos[0]-v.normal[0]*half,y=v.pos[1]-v.normal[1]*half;i===points.length-1?hole.moveTo(x,y):hole.lineTo(x,y);}hole.closePath();shape.holes.push(hole);const geo=new T.ExtrudeGeometry(shape,{depth:d.thickness,bevelEnabled:false});geo.translate(0,0,-half);const mesh=new T.Mesh(geo,new T.MeshStandardMaterial({color:d.color,roughness:.88}));mesh.castShadow=true;mesh.receiveShadow=true;const g=new T.Group();g.userData.dynamic=true;g.add(mesh);return g;}
export const beltIcon=()=>'<svg viewBox="0 0 120 58" aria-hidden="true"><path d="M32 12H87a17 17 0 0 1 0 34H32a17 17 0 0 1 0-34Z" fill="none" stroke="#a77546" stroke-width="5"/></svg>';
